function pageTransform(progress,backwards){const angle=(backwards?1:-1)*progress*178;return `rotateY(${angle}deg) translateZ(${Math.sin(progress*Math.PI)*18}px)`;}
function createPageLeaf(book,departing,backwards){
 book.querySelectorAll('.turn-leaf,.turn-shadow').forEach(e=>e.remove());
 const leaf=document.createElement('div');leaf.className='turn-leaf'+(backwards?' backwards':'');leaf.inert=true;leaf.setAttribute('aria-hidden','true');
 const face=document.createElement('div');face.className='leaf-face';
 const width=book.clientWidth,height=book.clientHeight;
 departing.className='departing-page';departing.style.width=width+'px';departing.style.height=height+'px';departing.style.padding=getComputedStyle(book).padding;
 departing.querySelectorAll('.turn-leaf,.turn-shadow').forEach(e=>e.remove());
 departing.querySelectorAll('[id]').forEach(e=>e.removeAttribute('id'));
 // cloneNode does not reliably copy the live value or the inner scrolling position.
 
 const scroll=departing.querySelector('.page-content');
 face.append(departing);leaf.append(face);book.append(leaf);if(scroll)scroll.scrollTop=Number(scroll.dataset.turnScroll)||0;
 const shadow=document.createElement('div');shadow.className='turn-shadow'+(backwards?' backwards':'');shadow.setAttribute('aria-hidden','true');book.append(shadow);
 return {leaf,shadow,backwards};
}
function positionPage(turn,progress){turn.leaf.style.transform=pageTransform(progress,turn.backwards);turn.shadow.style.opacity=String(Math.sin(progress*Math.PI)*.55);turn.shadow.style.transform=`scaleX(${Math.max(.05,1-progress)})`;}
function animatePageTurn(book,departing,backwards,progress=0){
 const turn=createPageLeaf(book,departing,backwards);positionPage(turn,progress);
 const animation=turn.leaf.animate([{transform:pageTransform(progress,backwards),opacity:1},{transform:pageTransform(1,backwards),opacity:0}],{duration:Math.max(140,340*(1-progress)),easing:'cubic-bezier(.2,.65,.25,1)',fill:'forwards'});
 turn.shadow.animate([{opacity:.4},{opacity:0}],{duration:340,fill:'forwards'});
 const finish=()=>{turn.leaf.remove();turn.shadow.remove();};animation.onfinish=finish;animation.oncancel=finish;
}
function cancelDaySwipe(){const s=daySwipe;daySwipe=null;if(!s?.turn)return;const t=s.turn;const animation=t.leaf.animate([{transform:pageTransform(s.progress,t.backwards)},{transform:pageTransform(0,t.backwards)}],{duration:140,easing:'ease-out'});animation.onfinish=()=>{t.leaf.remove();t.shadow.remove();};}
app.addEventListener('pointerdown',e=>{
 if(e.pointerType!=='touch'||!e.isPrimary||closed||section!=='calendar'||view!=='day'||modal.open)return;
 if(e.target.closest('button,input,textarea,select,a,canvas,[contenteditable],.month-tabs,.section-tabs,.named-ribbons')||window.getSelection()?.toString())return;
 const book=e.target.closest('[data-day-swipe]');if(!book)return;
 daySwipe={id:e.pointerId,x:e.clientX,y:e.clientY,time:performance.now(),date,book,progress:0};
});
app.addEventListener('pointermove',e=>{
 const s=daySwipe;if(!s||e.pointerId!==s.id)return;
 const dx=e.clientX-s.x,dy=e.clientY-s.y;
 if(!s.turn){if(Math.abs(dy)>10&&Math.abs(dy)>Math.abs(dx)){cancelDaySwipe();return;}if(Math.abs(dx)<8||Math.abs(dx)<Math.abs(dy)*1.2)return;
 s.backwards=dx>0;s.book.setPointerCapture(e.pointerId);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)s.turn=createPageLeaf(s.book,capturePage(s.book),s.backwards);s.horizontal=true;}
 const distance=Math.max(0,(s.backwards?1:-1)*dx);s.progress=Math.min(.8,distance/(s.book.clientWidth*.55));if(s.turn)positionPage(s.turn,s.progress);
});
app.addEventListener('pointercancel',cancelDaySwipe);
app.addEventListener('pointerup',e=>{
 const s=daySwipe;if(!s||s.id!==e.pointerId)return;
 const dx=e.clientX-s.x,dy=e.clientY-s.y,elapsed=performance.now()-s.time;
 if(closed||section!=='calendar'||view!=='day'||s.date!==date||modal.open||Math.abs(dx)<24||Math.abs(dx)<Math.abs(dy)*1.2||elapsed>2500||window.getSelection()?.toString()){cancelDaySwipe();return;}
 daySwipe=null;s.turn?.leaf.remove();s.turn?.shadow.remove();swipeTurnProgress=s.progress;navigate(dx<0?1:-1);
});

function renderLegacyGoals(){return `<div style="display:flex;justify-content:flex-end;margin-bottom:12px">${tools()}</div><section class="side-section"><h2>The bigger picture</h2>${ruled(`goals:${year()}:year`,'Your goals for the year','style="min-height:100px;height:100px"')}</section><div class="goals-grid">${months.map((m,i)=>`<section class="goal-box"><h2>${m}</h2>${ruled(`goals:${year()}:${i}`,`Goals for ${m}`)}<div class="goal-actions"><button class="text-action" data-goal-task="${i}">Make a task from this goal</button></div></section>`).join('')}</div>`;}
const customBuilder=createPlanningBuilder({blocked:()=>accountLocked||externalChange||storageCorrupt,entries:()=>state.entries,ink:()=>state.ink,notebookIdentity:()=>KEY,allowFinger:()=>!!state.settings.fingerDrawing,protectInk,save,render,toast,id,esc,current:()=>plannerPage,
 open:key=>{plannerMode='custom';plannerPage=key;plannerPinned=false;section='goals';closed=false;render();},
 library:()=>{plannerMode='custom';plannerPage=null;plannerPinned=false;section='goals';render();},
 schedule:({title,date:targetDate,source})=>{const linked=source&&entry(source+':calendar-event');if(linked){const existing=findEvent(linked);if(existing){eventForm(linked);return;}toast('The linked event is not available. Refresh Calendar before creating another.');return;}eventForm();const form=document.querySelector('#event-form');if(source)form.dataset.planningSource=source;form.querySelector('[name=title]').value=title||'Planning deadline';form.querySelector('[name=date]').value=targetDate;form.querySelector('[name=endDate]').value=targetDate;form.querySelector('[name=notes]').value='Created from a custom Planning Tools page.';}
});
const templateLibrary=createTemplateLibrary({entries:()=>state.entries,save,render,id,esc,openModal,closeModal,builder:customBuilder,current:()=>plannerPage,toast});
const customTemplate={id:'custom',title:'Custom planning page',summary:'A page assembled from your own reusable components.',sections:[],columns:[],group:'custom'};
function plannerRecords(){return Object.keys(state.entries).filter(k=>/^form:[a-z0-9-]+:type$/.test(k)).map(k=>{const key=k.split(':')[1],type=entry(k),template=type==='custom'?customTemplate:plannerTemplates.find(t=>t.id===type);return template?{key,template,title:entry(`form:${key}:title`)||template.title,archived:entry(`form:${key}:archived`)==='yes',pinned:entry(`form:${key}:pinned`)==='yes'}:null;}).filter(r=>r&&entry(`form:${r.key}:deleted`)!=='yes');}
function deleteFormButton(key){return `<button class="form-delete" data-planner-delete="${key}" aria-label="Delete form" title="Delete form"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg><span class="form-delete-label">Delete</span></button>`;}
function plannerKey(field){return `form:${plannerPage}:${field}`;}
function plannerTitle(){if(plannerPage==='legacy')return 'Your existing goals';const r=plannerRecords().find(r=>r.key===plannerPage);return r?r.title:plannerPinned?'My forms':plannerMode==='custom'?'Build Your Own':plannerMode==='forms'?'Choose from Forms':'Planning Tools';}
function plannerField(field,label,type='text'){const k=plannerKey(field),defaultTitle=field==='title'&&entry(k)==='My Planning Page';return `<label class="planner-label">${esc(label)}<input type="${type}" data-entry="${k}" ${defaultTitle?'data-select-default-title="true"':''} data-no-writing-tools data-no-quick-delete aria-label="${esc(label)}" value="${esc(entry(k))}"></label>`;}
const gym=Gym.createGymController({entries:()=>state.entries,form:()=>plannerPage,esc,save,render,id,openModal,closeModal,toast,confirmAction,snapshot,download,select:key=>{plannerPage=key;},fileInput:()=>document.querySelector('#gym-routine-file')});
document.addEventListener('change',async e=>{if(e.target.id==='gym-routine-file'){try{await gym.importFile(e.target.files[0]);}catch(err){toast(err.message);}e.target.value='';}else if(plannerRecords().find(r=>r.key===plannerPage)?.template.id==='gym')gym.changed(e.target);});
const packing=PackGo.createPackingController({entries:()=>state.entries,form:()=>plannerPage,esc,save,render,id,openModal,closeModal,toast,select:key=>{plannerPage=key;}});
document.addEventListener('change',e=>{if(plannerRecords().find(r=>r.key===plannerPage)?.template.id==='pack-go')packing.changed(e.target);});
document.addEventListener('change',e=>{if(plannerRecords().find(r=>r.key===plannerPage)?.template.id==='custom')customBuilder.changed(e.target);});
function renderPlanner(){
 if(plannerPage==='legacy')return `<button class="secondary" data-planner-home>All forms</button>${renderLegacyGoals()}`;
 const records=plannerRecords(),record=records.find(r=>r.key===plannerPage);
 if(record?.template.id==='custom')return renderBuilder({record,definition:customBuilder.get(record.key),entry,esc,undoAvailable:customBuilder.hasUndo(),editingTemplate:entry(`form:${record.key}:template-edit`)});
 if(record?.template.id==='gym')return compactFormToolbar(`<div class="planner-toolbar"><button class="secondary" data-planner-home>Choose from Forms</button><button class="secondary" data-planner-pin="${record.key}">${record.pinned?'Remove from My forms':'Add to My forms tab'}</button><button class="secondary" data-planner-copy="${record.key}">Copy into Build Your Own</button>${deleteFormButton(record.key)}</div><div class="planner-meta">${plannerField('title','Routine / session name')}</div>${gym.render()}`);
 if(record?.template.id==='pack-go')return compactFormToolbar(`<div class="planner-toolbar"><button class="secondary" data-planner-home>Choose from Forms</button><button class="secondary" data-planner-pin="${record.key}">${record.pinned?'Remove from My forms':'Add to My forms tab'}</button><button class="secondary" data-planner-copy="${record.key}">Copy into Build Your Own</button>${deleteFormButton(record.key)}</div><div class="planner-meta">${plannerField('title','Trip name')}</div>${packing.render()}`);
 if(record){const t=record.template,f=plannerFlows[t.id],count=Math.min(100,Math.max(4,Number(entry(plannerKey('rows')))||4));return compactFormToolbar(`<div class="planner-toolbar"><button class="secondary" data-planner-home>${plannerPinned?'My forms':'Choose from Forms'}</button><button class="secondary" data-planner-pin="${record.key}" aria-pressed="${record.pinned}">${record.pinned?'Remove from My forms':'Add to My forms tab'}</button><button class="secondary" data-planner-copy="${record.key}">Copy into Build Your Own</button>${deleteFormButton(record.key)}</div><div class="planner-meta">${plannerField('title','Name this form')}${plannerField('date',t.group==='plan'?'Target date (optional)':'Review date (optional)','date')}</div><section class="planner-section"><h2>1. ${esc(f.contextTitle)}</h2><p class="planner-guide">${esc(f.contextGuide)}</p>${ruled(plannerKey('flow-context'),f.contextTitle,'data-no-quick-delete')}</section><section class="planner-register"><h2>2. ${esc(f.tableTitle)}</h2><p class="planner-guide">One item per row. Fill only what helps; add rows as you need them. Tick a row when finished.</p><div class="planner-table-scroll"><table class="planner-table"><thead><tr><th scope="col">Done</th>${f.columns.map(c=>`<th scope="col">${esc(c)}</th>`).join('')}</tr></thead><tbody>${Array.from({length:count},(_,r)=>`<tr class="${entry(plannerKey('flow-done-'+r))==='yes'?'planner-row-done':''}"><td><button class="habit-check ${entry(plannerKey('flow-done-'+r))==='yes'?'checked':''}" data-planner-done="${r}" aria-label="Mark row ${r+1} done" aria-pressed="${entry(plannerKey('flow-done-'+r))==='yes'}">${entry(plannerKey('flow-done-'+r))==='yes'?'✓':''}</button></td>${f.columns.map((c,i)=>`<td data-label="${esc(c)}">${ruled(plannerKey(`flow-cell-${r}-${i}`),`${c}, row ${r+1}`,'data-no-quick-delete')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${count<100?'<button class="text-action" data-planner-row>Add a row</button>':''}</section><details class="planner-extra" ${entry(plannerKey('flow-note'))?'open':''}><summary>3. ${esc(f.noteTitle)} (optional)</summary><p class="planner-guide">${esc(f.noteGuide)}</p>${ruled(plannerKey('flow-note'),f.noteTitle,'data-no-quick-delete')}</details>${plannerPrevious(record,count)}<details class="planner-extra" ${entry(plannerKey('next'))?'open':''}><summary>Create a task or reserve time</summary><p class="planner-guide">Choose an action from your list to send to your to-do list or calendar.</p>${ruled(plannerKey('next'),'Action to schedule','data-no-quick-delete')}<div class="planner-toolbar"><button class="secondary" data-planner-task>Make a task</button><button class="secondary" data-planner-event>Schedule time</button><span class="planner-saving" data-saving-status></span></div></details>`);}
 if(plannerPinned){plannerPage=null;const pinned=records.filter(r=>r.pinned&&!r.archived);return `<div class="planner-toolbar"><button class="secondary" data-planner-library>Browse all forms</button></div><div class="planner-cards">${pinned.map(r=>`<button class="planner-card" data-planner-open="${r.key}"><strong>${esc(r.title)}</strong><span>${esc(r.template.title)}</span></button>`).join('')||'<p class="empty-note">Open a saved form and choose “Add to My forms tab” to keep it here.</p>'}</div>`;}

 if(plannerMode==='custom')return renderCustomLibrary({records:records.filter(r=>r.template.id==='custom'),esc});
 if(!plannerMode)return `<div class="planner-choice"><button data-planner-choice="custom"><span class="planner-choice-icon">✦</span><strong>Build Your Own</strong><span>Arrange notes, tick-lists, drawings, voice memos, ratings, timers, deadlines and locations on your own page.</span></button><button data-planner-choice="forms"><span class="planner-choice-icon">▦</span><strong>Choose from Forms</strong><span>Browse the existing organised collection, complete a form and return to it later.</span></button></div>`;

 plannerPage=null;const templateRecords=records.filter(r=>r.template.id!=='custom'),active=templateRecords.filter(r=>!r.archived).sort((a,b)=>Number(b.pinned)-Number(a.pinned)),archived=templateRecords.filter(r=>r.archived);
 if(plannerManagingForms)return `<div class="planner-hub planner-management"><div class="planner-toolbar"><button class="text-action" data-planner-manage-back>‹ Choose from Forms</button></div><section class="my-forms-management"><h2>My Forms</h2><p class="planner-guide">Your saved forms and plans. Pick up where you left off.</p><label class="planner-search-label">Search saved forms<input type="search" id="planner-saved-search" data-no-writing-tools placeholder="Search saved forms..." autocomplete="off" value="${esc(plannerSavedSearch)}"></label><div class="planner-saved-list">${active.map(r=>`<button class="planner-saved-item" data-planner-open="${r.key}" data-saved-match="${esc((r.title+' '+r.template.title).toLowerCase())}"><strong>${esc(r.title)}</strong><span>${esc(r.template.title)}${entry(`form:${r.key}:date`)?' · '+esc(entry(`form:${r.key}:date`)):''}</span></button>`).join('')||'<p class="planner-guide">No forms saved yet. Forms you start using will appear here.</p>'}<p id="planner-saved-no-match" class="planner-guide" hidden>No saved forms match this search.</p>${archived.length?`<details><summary>Archived forms (${archived.length})</summary>${archived.map(r=>`<button class="planner-saved-item" data-planner-open="${r.key}">${esc(r.title)}</button>`).join('')}</details>`:''}<button class="text-action planner-legacy" data-planner-legacy>Your existing goals</button></div></section>${templateLibrary.html()}</div>`;
 const recent=active.slice().sort((a,b)=>(entry(`form:${b.key}:accessed`)||entry(`form:${b.key}:edited`)||'').localeCompare(entry(`form:${a.key}:accessed`)||entry(`form:${a.key}:edited`)||'')).slice(0,3);
 return `<div class="planner-hub planner-explore"><div class="planner-toolbar"><button class="text-action planner-back" data-planner-root>‹ <span>Planning Tools</span></button></div><section class="planner-my-forms"><div class="planner-section-heading"><div><h2>My Forms</h2><p class="planner-guide">Your saved forms and plans. Pick up where you left off.</p></div><button class="text-action" data-planner-manage>${active.length?'View All':'Manage My Forms'}</button></div>${recent.length?`<div class="planner-recent-list">${recent.map(r=>`<button class="planner-recent-item" data-planner-open="${r.key}"><span class="planner-recent-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${plannerIcons[plannerHomeCategory(r.template)?.id]||'<path d="M5 3h14v18H5zM8 8h8M8 12h8M8 16h5"/>'}</svg></span><span><strong>${esc(r.title)}</strong><small>${esc(r.template.title)} · ${plannerEditedLabel(r.key)}</small></span></button>`).join('')}</div>${active.length>3?'<button class="text-action planner-manage-link" data-planner-manage>View All My Forms</button>':''}`:'<p class="planner-empty">No forms saved yet <small>Forms you start using will appear here.</small></p>'}</section><section class="planner-explore-forms"><h2>Explore Forms</h2><p class="planner-guide">Ready-made forms for everyday planning.</p><label class="planner-search-label"><span class="sr-only">Search forms</span><input type="search" id="planner-search" data-no-writing-tools placeholder="Search forms..." autocomplete="off" value="${esc(plannerSearch)}"></label><div id="planner-catalogue">${plannerCatalogue()}</div></section></div>`;

}
function plannerHomeCategory(t){return plannerCategories.find(c=>c.templates.includes(t.id));}
function plannerEditedLabel(key){const value=entry(`form:${key}:edited`);if(!value)return 'Ready to continue';const d=new Date(value);if(!Number.isFinite(d.getTime()))return 'Recently edited';const days=Math.floor((Date.now()-d.getTime())/86400000);return days<1?'Edited today':days===1?'Edited yesterday':`Edited ${days} days ago`;}
function plannerMatch(t){const home=plannerHomeCategory(t),related=(plannerRelated[t.id]||[]).map(id=>plannerCategories.find(c=>c.id===id)?.title||'');return [t.title,t.summary,home.title,home.summary,...related,...t.sections.map(s=>s.title+' '+s.guide)].join(' ').toLowerCase();}
function plannerCatalogue(){
 const query=plannerSearch.toLowerCase().trim(),category=plannerCategories.find(c=>c.id===plannerCategory);
 if(!query&&!category)return `<div class="planner-category-grid">${plannerCategories.map(c=>`<button class="planner-category-card category-${esc(c.id)}" data-planner-category="${c.id}"><span class="planner-category-heading"><svg class="planner-category-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${plannerIcons[c.id]}</svg><strong>${esc(c.title)}</strong></span><small>${plannerTemplates.filter(t=>!['morning','evening'].includes(t.id)&&(c.templates.includes(t.id)||(plannerRelated[t.id]||[]).includes(c.id))).length} forms <span aria-hidden="true">›</span></small></button>`).join('')}</div>`;
 const templates=plannerTemplates.filter(t=>!['morning','evening'].includes(t.id)).filter(t=>query?plannerMatch(t).includes(query):category.templates.includes(t.id)||(plannerRelated[t.id]||[]).includes(category.id));
 return `<div class="planner-catalogue-heading"><button class="text-action" data-planner-categories>All sections</button><h2 class="planner-catalogue-title">${query?'Search results':esc(category.title)}</h2><span class="planner-result-count" role="status">${templates.length} ${templates.length===1?'form':'forms'}${query?' across all sections':''}</span></div>${!query?`<p class="planner-guide">${esc(category.summary)}</p>`:''}<div class="planner-cards">${templates.map(t=>`<button class="planner-card" data-planner-template="${t.id}"><strong>${esc(t.title)}</strong><span>${esc(t.summary)}</span><small>${esc(plannerHomeCategory(t).title)}</small></button>`).join('')}</div>${templates.length?'':'<p class="empty-note">No matching templates. Try “packing” or “budget”, or check My forms for a saved copy.</p>'}`;
}
function plannerFilterSaved(){const query=(plannerManagingForms?plannerSavedSearch:plannerSearch).toLowerCase().trim(),buttons=app.querySelectorAll('[data-saved-match]');let count=0;buttons.forEach(b=>{b.hidden=!b.dataset.savedMatch.includes(query);if(!b.hidden)count++;});const message=document.querySelector('#planner-saved-no-match');if(message)message.hidden=!query||count>0||!buttons.length;}
function plannerPrevious(record,count){const t=record.template,hasOld=t.sections.some((_,i)=>entry(plannerKey('section-'+i)))||Array.from({length:count},(_,r)=>t.columns.some((_,c)=>entry(plannerKey(`cell-${r}-${c}`)))).some(Boolean);if(!hasOld)return '';return `<details class="planner-extra"><summary>Your previous answers</summary><p class="planner-guide">Your earlier writing is kept here with its original headings. You can still edit it.</p>${t.sections.map((x,i)=>entry(plannerKey('section-'+i))?`<section><h2>${esc(x.title)}</h2>${ruled(plannerKey('section-'+i),x.title,'data-no-quick-delete')}</section>`:'').join('')}<div class="planner-table-scroll"><table class="planner-table"><thead><tr>${t.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${Array.from({length:count},(_,r)=>t.columns.some((_,c)=>entry(plannerKey(`cell-${r}-${c}`)))?`<tr>${t.columns.map((c,i)=>`<td>${ruled(plannerKey(`cell-${r}-${i}`),`${c}, previous row ${r+1}`,'data-no-quick-delete')}</td>`).join('')}</tr>`:'').join('')}</tbody></table></div></details>`;}
function plannerNew(type){const t=plannerTemplates.find(t=>t.id===type);if(!t)return;openModal('Start '+esc(t.title),`<form id="planner-create" data-template="${t.id}"><label class="planner-label">Name this form<input name="title" type="text" maxlength="120" value="${esc(t.title)}" required autofocus></label><p>${esc(t.summary)}</p><div class="modal-footer"><button type="button" class="secondary" data-action="close-modal">Cancel</button><button type="submit" class="primary">Create form</button></div></form>`);}
function plannerClick(data){
 if(Object.keys(data).some(key=>key.startsWith('template'))){try{return templateLibrary.handle(data);}catch(err){toast(err.message);return true;}}
 if('plannerRoot'in data){plannerMode=null;plannerPinned=false;plannerManagingForms=false;plannerPage=null;plannerCategory=null;plannerSearch='';section='goals';render();return true;}
 if('plannerManage'in data){plannerManagingForms=true;plannerSavedSearch='';plannerCategory=null;plannerSearch='';render();return true;}
 if('plannerManageBack'in data){plannerManagingForms=false;render();return true;}
 if(data.plannerChoice){templateLibrary.reset();plannerMode=data.plannerChoice==='custom'?'custom':'forms';plannerManagingForms=false;plannerPinned=false;plannerPage=null;render();return true;}
 if(Object.keys(data).some(key=>key.startsWith('custom'))){customBuilder.handle(data).catch(err=>toast(err.message));return true;}
 if('plannerLibrary'in data){plannerMode='forms';plannerPinned=false;plannerPage=null;section='goals';render();return true;}
 if(data.plannerPin){const k=`form:${data.plannerPin}:pinned`;state.entries[k]=entry(k)==='yes'?'no':'yes';if(entry(k)==='yes'){state.entries[`form:${data.plannerPin}:archived`]='no';if(entry(`form:${data.plannerPin}:type`)==='custom')customBuilder.finish(data.plannerPin);}save();render();toast(entry(k)==='yes'?'Added to My forms.':'Removed from My forms.');return true;}
 if('plannerDone'in data){const k=plannerKey('flow-done-'+data.plannerDone);state.entries[k]=entry(k)==='yes'?'no':'yes';save();render();return true;}

 if(data.plannerCategory){plannerPinned=false;plannerCategory=data.plannerCategory;plannerSearch='';plannerPage=null;render();return true;}
 if('plannerCategories'in data){plannerCategory=null;plannerSearch='';render();return true;}
 if('plannerHome'in data){if(!plannerMode)plannerMode='forms';plannerManagingForms=false;plannerPage=null;render();return true;}
 if('plannerLegacy'in data){plannerPage='legacy';render();return true;}
 if(data.plannerTemplate){plannerNew(data.plannerTemplate);return true;}
 if(data.plannerOpen){section='goals';closed=false;plannerPage=data.plannerOpen;state.entries[`form:${plannerPage}:accessed`]=new Date().toISOString();save();plannerMode=plannerRecords().find(r=>r.key===plannerPage)?.template.id==='custom'?'custom':'forms';render();return true;}
 if(data.plannerCopy){const record=plannerRecords().find(r=>r.key===data.plannerCopy);if(record&&record.template.id!=='custom'){const title=record.title+' — custom';customBuilder.create(title,definitionFromTemplate(record.template,plannerFlows[record.template.id],title));toast('Copied into Build Your Own.');}return true;}
 if(data.plannerDelete){const key=data.plannerDelete;confirmAction('Delete form','Delete this planning sheet? Your reusable template and other filled sheets will be kept.',()=>{snapshot();state.entries[`form:${key}:deleted`]='yes';state.entries[`form:${key}:pinned`]='no';save();plannerPage=null;render();});return true;}
 if(data.plannerArchive){const k=`form:${data.plannerArchive}:archived`;state.entries[k]=entry(k)==='yes'?'no':'yes';save();plannerPage=null;render();return true;}
 if('plannerRow'in data){state.entries[plannerKey('rows')]=String(Math.min(100,(Number(entry(plannerKey('rows')))||4)+1));save();render();return true;}
 if('plannerTask'in data&&!entry(plannerKey('next')).trim()||'plannerEvent'in data&&!entry(plannerKey('next')).trim()){toast('Write the action you want to schedule first.');return true;}
 if('plannerTask'in data){taskForm(null,entry(plannerKey('next')).split('\n')[0]||plannerTitle());const f=document.querySelector('#task-form');f.querySelector('[name=notes]').value=`From Planning Tools: ${plannerTitle()}\n${entry(plannerKey('next'))}`;const d=entry(plannerKey('date'));if(d)f.querySelector('[name=date]').value=d;return true;}
 if('plannerEvent'in data){eventForm();const f=document.querySelector('#event-form');f.querySelector('[name=title]').value=entry(plannerKey('next')).split('\n')[0]||plannerTitle();f.querySelector('[name=notes]').value=`From Planning Tools: ${plannerTitle()}\n${entry(plannerKey('next'))}`;const d=entry(plannerKey('date'));if(d){f.querySelector('[name=date]').value=d;f.querySelector('[name=endDate]').value=d;}return true;}
 return false;
}
document.addEventListener('input',e=>{if(e.target.id==='planner-search'){plannerSearch=e.target.value;document.querySelector('#planner-catalogue').innerHTML=plannerCatalogue();plannerFilterSaved();}if(e.target.id==='planner-saved-search'){plannerSavedSearch=e.target.value;plannerFilterSaved();}customBuilder.input(e.target);if(e.target.dataset.entry?.startsWith('form:')&&e.target.dataset.entry.endsWith(':title')){const h=app.querySelector('.book-head h1');if(h)h.textContent=e.target.value||'Planning Tools';}});
document.addEventListener('focusin',e=>{const field=e.target,isDefaultTitle=field.matches('input[data-entry^="form:"][data-entry$=":title"]')&&field.value.trim().toLocaleLowerCase('en-GB')==='my planning page';if(isDefaultTitle)queueMicrotask(()=>{if(document.activeElement===field&&field.value.trim().toLocaleLowerCase('en-GB')==='my planning page')field.select();});});

document.addEventListener('input',e=>templateLibrary.input(e.target));

// Account foundation: local keys and recovery mirrors are scoped before loading.
accountManager=mountAccounts({getState:()=>state,empty:emptyState,
 apply:(content,cloud)=>{applyCloudContent(content);state._cloud=cloud;if(!state.notes.some(n=>n.id===noteId))noteId=state.notes[0]?.id||null;},
 persist:async()=>{if(accountLocked||externalChange||storageCorrupt)throw Error('Local notebook needs reload/recovery');state.savedAt=new Date().toISOString();const copy=structuredClone(state);let localOK=false;try{localStorage.setItem(KEY,JSON.stringify(copy));localOK=true;}catch{}mirrorQueue=mirrorQueue.catch(()=>{}).then(()=>writeMirror(copy,KEY));try{await mirrorQueue;storageError=false;}catch{storageError=!localOK;if(!localOK)throw Error('Local recovery storage unavailable. Export immediately.');}updateSaveStatus();},
 finishLocal:()=>mirrorQueue.catch(()=>{}),
 blocked:()=>externalChange||accountLocked||storageCorrupt||!!inkDrawing||drawingPointers.size>0||document.activeElement?.matches('input,textarea,[contenteditable=true]'),onStatus:updateSaveStatus,render:()=>{if(startupReady&&!inkDrawing&&!['notes','launchpad','tasks','goals'].includes(section))render();},openModal,closeModal,toast,snapshot,
 exportNotebook:()=>{const {_cloud,...copy}=state;download('unbound-account-export.json',JSON.stringify(copy,null,2),'application/json');},
 lock:()=>{dictation.dismiss();customBuilder.cancelRecording();noteMedia.cancel();accountLocked=true;clearTimeout(taskSyncTimer);Google.disconnect();Dropbox.disconnect();document.querySelector('#app').inert=true;document.querySelector('#modal').inert=true;},
 // Cloud snapshots omit device-only preferences and Google caches by design.
 // Validate a hydrated copy without modifying the stored cloud payload.
 validateBackup:(data)=>validateBackup({...emptyState(),...data,
   settings:{...emptyState().settings,...data.settings},
   cachedGoogle:[],googleCalendars:[]}),
});

// The account-scoped local notebook and recovery copy are ready. Cloud
// reconciliation started in mountAccounts and can finish after the first paint.
try{const draft=JSON.parse(localStorage.getItem(KEY+'-active-ink')||'null');if(draft&&Array.isArray(draft.paths)&&(state.notes.some(n=>n.id===draft.key)||draft.key.startsWith('planner:'))&&draft.updatedAt>(Date.parse(state.savedAt)||0)){state.ink[draft.key]=draft.paths;save();}if(!storageError)localStorage.removeItem(KEY+'-active-ink');}catch{}

startupReady=true;
render();
performance.mark('unbound:app-ready');
performance.measure('unbound:startup-to-visible',{start:0,end:'unbound:app-ready'});
document.querySelector('.app-bar').inert=false;
if(launchQuickCapture)queueMicrotask(()=>showQuickCapture(incomingShare));

// Restore the account-bound grant on every device, reload and foreground return.
let restoringGoogle=false,googleRestoreError='',googleRestoreNotified=false;
async function restoreAccountGoogle(){
 if(restoringGoogle||accountLocked||!Accounts.user||!navigator.onLine)return;
 restoringGoogle=true;
 try{
  if(!await Google.restoreConnection()){googleRestoreError='Google access needs consent. Choose Connect Google Calendar, Tasks & Drive in Settings.';return;}
  googleRestoreError='';googleRestoreNotified=false;
  state.settings.backupProvider='google';
  await refreshGoogle();
  if(Google.tasksConnected())await syncTasks();
  if(Google.backupConnected())await runCloudBackup();
 }catch(e){googleRestoreError=e.message;taskSyncStatus=e.message;if(!googleRestoreNotified){toast(e.message);googleRestoreNotified=true;}}finally{restoringGoogle=false;updateSaveStatus();const error=document.querySelector('#google-error');if(error)error.textContent=googleRestoreError;}
}
if(Accounts.client&&Accounts.user){
 Google.configureAccountConnection({
  enabled:()=>!accountLocked&&!!Accounts.user,
  credentials:Accounts.googleCredentials,
  invoke:async body=>{const response=await Accounts.client.functions.invoke('google-connection',{body});if(!response.error&&body.action==='store')Accounts.clearGoogleCredentials();return response;}
 });
 restoreAccountGoogle();
 window.addEventListener('online',restoreAccountGoogle);
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')restoreAccountGoogle();});
 setInterval(()=>{if(document.visibilityState==='visible')restoreAccountGoogle();},60000);
}
